package com.clearchoice;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Rect;import android.view.*;import android.view.accessibility.*;import java.util.*;
/** Real test-only source Activity and real accessibility windows. No retailer E2E or screenshots. */
public final class PriceAnnotationInstrumentation extends Instrumentation {
 int checks;ClearChoiceService service;UiAutomation ui;SharedPreferences prefs;HashMap<String,Boolean> prior=new HashMap<>();
 void require(boolean yes,String why){if(!yes)throw new AssertionError(why);checks++;}
 void main(Runnable task){Throwable[] error={null};runOnMainSync(()->{try{task.run();}catch(Throwable e){error[0]=e;}});if(error[0]!=null)throw new AssertionError(error[0]);}
 boolean attached(){boolean[] value={false};main(()->value[0]=service.priceLayer!=null&&service.priceLayer.isAttached());return value[0];}
 void await(boolean shown)throws Exception{long end=SystemClock.uptimeMillis()+5000;while(SystemClock.uptimeMillis()<end){if(attached()==shown)return;Thread.sleep(60);}String[] debug={""};main(()->{AccessibilityNodeInfo root=service.getRootInActiveWindow();ArrayList<PriceEvidenceParser.Line> lines=new ArrayList<>();boolean collected=root!=null&&service.collectRetail(root,"0",0,lines);debug[0]=" state="+Engine.state(service)+" gen="+service.retailGeneration+" root="+(root==null?"null":root.getPackageName())+" collected="+collected+" lines="+lines.size()+" parsed="+(PriceEvidenceParser.parse(lines)!=null)+" layer="+(service.priceLayer==null?"null":service.priceLayer.lastFailure+" mark="+(service.priceLayer.mark!=null));});throw new AssertionError("Expected attached="+shown+" actual="+attached()+debug[0]);}
 AccessibilityNodeInfo find(AccessibilityNodeInfo n,String text){if(n==null)return null;if(text.equalsIgnoreCase(String.valueOf(n.getText())))return n;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo found=find(n.getChild(i),text);if(found!=null)return found;}return null;}
 AccessibilityNodeInfo source(String text){AccessibilityNodeInfo[] found={null};main(()->{AccessibilityNodeInfo root=service.priceForegroundRoot();if(root!=null&&"com.clearchoice.test".equals(String.valueOf(root.getPackageName())))found[0]=find(root,text);});return found[0];}
 AccessibilityNodeInfo scroll(AccessibilityNodeInfo n){if(n==null)return null;if(n.isScrollable())return n;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo s=scroll(n.getChild(i));if(s!=null)return s;}return null;}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle out=new Bundle();try{
  ui=getUiAutomation(UiAutomation.FLAG_DONT_SUPPRESS_ACCESSIBILITY_SERVICES);AccessibilityServiceInfoCompat();long end=SystemClock.uptimeMillis()+10000;while(ClearChoiceService.liveService==null&&SystemClock.uptimeMillis()<end)Thread.sleep(100);service=ClearChoiceService.liveService;if(service==null)throw new AssertionError("Connected accessibility service required");prefs=service.getSharedPreferences("cc",0);String[] keys={"app_enabled","paused","startup","internal_qa","allow:com.clearchoice.test"};for(String key:keys)prior.put(key,prefs.contains(key)?prefs.getBoolean(key,false):null);prefs.edit().putBoolean("app_enabled",true).putBoolean("paused",false).putBoolean("startup",true).putBoolean("internal_qa",true).putBoolean("allow:com.clearchoice.test",true).commit();getContext().startActivity(new Intent().setComponent(new ComponentName("com.clearchoice.test","com.clearchoice.PriceSourceTestActivity")).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));Thread.sleep(500);getTargetContext().sendBroadcast(new Intent("com.clearchoice.PAUSE_CHANGED").setPackage("com.clearchoice"));await(true);Thread.sleep(350);
  AccessibilityNodeInfo price=source("Subtotal SGD 10.00");require(price!=null,"Actual source price observed through accessibility");Rect bounds=new Rect();price.getBoundsInScreen(bounds);final View[] originalWindows=new View[2];final int[] stable={0};
  main(()->{require(service.priceLayer.isAttached(),"Actual mark and badge attached after traversal");require(!service.priceLayer.result.complete,"Missing mandatory fees stays incomplete");WindowManager.LayoutParams stroke=(WindowManager.LayoutParams)service.priceLayer.mark.getLayoutParams(),badge=(WindowManager.LayoutParams)service.priceLayer.badge.getLayoutParams();require(stroke.x==bounds.left&&stroke.y==bounds.top&&stroke.width==bounds.width()&&stroke.height==bounds.height(),"Mark follows real observed source bounds");require((stroke.flags&WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE)!=0,"Mark is pass-through");require((badge.flags&WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE)!=0&&(badge.flags&WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL)!=0,"Original controls and keyboard remain native");require(badge.width>0&&badge.height==-2,"Badge is never fullscreen");originalWindows[0]=service.priceLayer.mark;originalWindows[1]=service.priceLayer.badge;stable[0]=service.retailGeneration;});Thread.sleep(700);main(()->require(service.priceLayer.mark==originalWindows[0]&&service.retailGeneration==stable[0],"Real own-window events do not loop/recreate annotation"));
  long t=SystemClock.uptimeMillis();MotionEvent down=MotionEvent.obtain(t,t,MotionEvent.ACTION_DOWN,bounds.centerX(),bounds.centerY(),0),up=MotionEvent.obtain(t,t+80,MotionEvent.ACTION_UP,bounds.centerX(),bounds.centerY(),0);require(ui.injectInputEvent(down,true)&&ui.injectInputEvent(up,true),"Real tap injected at marked original price");down.recycle();up.recycle();Thread.sleep(450);require(source("Subtotal SGD 11.00")!=null,"Native source button received tap through price stroke");await(true);main(()->{require(service.priceLayer.result.amount.toPlainString().equals("11.00"),"Updated source price parsed after content revision");require(!originalWindows[0].isAttachedToWindow()&&!originalWindows[1].isAttachedToWindow(),"Old annotation windows actually detached after revision");originalWindows[0]=service.priceLayer.mark;originalWindows[1]=service.priceLayer.badge;});
  AccessibilityNodeInfo scrolling=scroll(service.priceForegroundRoot());require(scrolling!=null&&scrolling.performAction(AccessibilityNodeInfo.ACTION_SCROLL_FORWARD),"Original internal source scrolled");await(false);main(()->require(!originalWindows[0].isAttachedToWindow()&&!originalWindows[1].isAttachedToWindow(),"Scroll removes actual stale windows when price leaves viewport"));
  require(scrolling.performAction(AccessibilityNodeInfo.ACTION_SCROLL_BACKWARD),"Original internal source scrolled back");await(true);main(()->{originalWindows[0]=service.priceLayer.mark;originalWindows[1]=service.priceLayer.badge;prefs.edit().putBoolean("paused",true).commit();service.pauseReceiver.onReceive(service,new Intent("com.clearchoice.PAUSE_CHANGED"));});await(false);waitForIdleSync();main(()->require(!originalWindows[0].isAttachedToWindow()&&!originalWindows[1].isAttachedToWindow(),"Pause actually detaches mark and badge"));
  out.putString("result",checks+" internal source-to-annotation checks passed: real source bounds, real native tap pass-through, price revision, scrolling, pause and own-window stability. No retailer E2E or recordings.");finish(0,out);
 }catch(Throwable e){out.putString("result",e.toString());finish(1,out);}finally{if(service!=null){main(()->service.clearRetailPrice());if(prefs!=null){SharedPreferences.Editor edit=prefs.edit();for(Map.Entry<String,Boolean> item:prior.entrySet())if(item.getValue()==null)edit.remove(item.getKey());else edit.putBoolean(item.getKey(),item.getValue());edit.commit();}}}}
 void AccessibilityServiceInfoCompat(){android.accessibilityservice.AccessibilityServiceInfo info=ui.getServiceInfo();info.flags|=android.accessibilityservice.AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS|android.accessibilityservice.AccessibilityServiceInfo.FLAG_REPORT_VIEW_IDS;ui.setServiceInfo(info);}
}
